            "value": {
              "type": "object",
              "properties": {
                "copied": {
                  "type": "array",
                  "items": {
                    "type": "object",
                    "properties": {
                      "from": {
                        "$ref": "lawbench://contracts/common.schema.json#/$defs/abs_path"
                      },
                      "to": {
                        "$ref": "lawbench://contracts/common.schema.json#/$defs/rel_path"
                      }
                    },
                    "additionalProperties": false,
                    "required": [
                      "from",
                      "to"
                    ]
                  }
