                "skipped": {
                  "type": "array",
                  "items": {
                    "type": "object",
                    "properties": {
                      "path": {
                        "$ref": "lawbench://contracts/common.schema.json#/$defs/abs_path"
                      },
                      "reason": {
                        "enum": [
                          "链接或快捷方式",
                          "同名同内容已存在",
                          "无法读取",
                          "超过大小上限",
                          "不能登记的位置",
                          "已经登记过",
                          "文件太多"
                        ]
                      }
                    },
                    "additionalProperties": false,
                    "required": [
                      "path",
                      "reason"
                    ]
                  }
                },
                "scan": {
                  "$ref": "lawbench://contracts/api/materials_scan.schema.json#/$defs/value"
                },
                "registered": {
                  "type": "array",
                  "items": {
                    "type": "object",
                    "properties": {
