    return response.json;
  }
  const hasValue =
    response.json &&
    Object.prototype.hasOwnProperty.call(response.json, "value");
  check(
    response.json &&
      response.json.ok === true &&
      hasValue,
    `${method} ${pathname} response envelope`,
  );
  return response.json.value;
}

